CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, university VARCHAR(200) DEFAULT '', major VARCHAR(200) DEFAULT '', bio VARCHAR(1000) DEFAULT '', location VARCHAR(200) DEFAULT '', career_goal VARCHAR(200) DEFAULT '', skills TEXT DEFAULT '[]', language VARCHAR(10) DEFAULT 'en');
CREATE TABLE IF NOT EXISTS sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS teams (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(500) DEFAULT '', university VARCHAR(200) DEFAULT '', category VARCHAR(100) DEFAULT '', owner_id BIGINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS team_members (team_id BIGINT NOT NULL REFERENCES teams(id), user_id BIGINT NOT NULL REFERENCES users(id), PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS courses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200), category VARCHAR(100), provider VARCHAR(150));
CREATE TABLE IF NOT EXISTS partners (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200), type VARCHAR(100), location VARCHAR(150));
CREATE TABLE IF NOT EXISTS messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sender_id BIGINT NOT NULL REFERENCES users(id), recipient_id BIGINT NOT NULL REFERENCES users(id), content VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), type VARCHAR(40), title VARCHAR(300), is_read BOOLEAN DEFAULT FALSE, created_at VARCHAR(40));
CREATE TABLE IF NOT EXISTS friendships (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requester_id BIGINT REFERENCES users(id), addressee_id BIGINT REFERENCES users(id), status VARCHAR(20) DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS enrollments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), course_id BIGINT REFERENCES courses(id), progress INTEGER DEFAULT 0, UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS exchanges (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), target_id BIGINT REFERENCES users(id), status VARCHAR(20) DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS preferences (user_id BIGINT PRIMARY KEY REFERENCES users(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inquiries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), message VARCHAR(1000));
CREATE TABLE IF NOT EXISTS analyses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), role VARCHAR(150), score INTEGER, matched TEXT, missing TEXT);
CREATE TABLE IF NOT EXISTS career_access (user_id BIGINT PRIMARY KEY REFERENCES users(id), free_used BOOLEAN NOT NULL DEFAULT FALSE, pro_until BIGINT NOT NULL DEFAULT 0, active_request VARCHAR(36), active_until BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS career_results (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, result_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS career_results_owner ON career_results(user_id,created_at);
ALTER TABLE career_access ADD COLUMN IF NOT EXISTS active_canceled BOOLEAN NOT NULL DEFAULT FALSE;
